protocol Named { var name: String { get } }
protocol Aged { var age: Int { get } }
struct Cat: Named, Aged {
    let name = "Bo"; let age = 3 }
let pet: any Named & Aged = Cat()
print(pet.name, pet.age)

protocol Listener: AnyObject { func ping() }
final class Logger: Listener {
    func ping() { print("ping") }
}
let logger = Logger()
weak var l: Listener? = logger; l?.ping()

protocol Doubler { func twice() -> Self }
extension Int: Doubler {
    func twice() -> Int { self * 2 }
}
print(5.twice())

